// Mechanical inventory, exact generated delivery pin and authenticated preimages.
import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-imaging-desktop-layout',site=stage+'/website',prep=json(stage+'/PREPARATION.json'),parent=json(prep.parentReceipt),write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'});
assert.equal(hash(prep.parentReceipt),'89711b205a711008b0fcc1524acb15d5fa2d16e752fc5962fcce679d6375f6b7');
for(const phase of ['bind-v3','viewer-v2','prebuild','build','verify','types'])assert.equal(json(stage+'/checks/'+phase+'/TERMINAL.json').code,0,phase);
const binding=json(site+'/atlas-review/integration-inputs.json'),oldBinding=json(parent.website+'/atlas-review/integration-inputs.json');assert.equal(binding.inputs.length,1786);
const added=['components/AtlasRegionNavigation.tsx','components/AtlasWorkspaceNavigation.tsx','lib/head-practice-navigation.ts'],changed=['components/HeadAtlasViewer.tsx','components/ImagingAtlasShell.tsx','scripts/bind-clinical-review.mjs'];
const oldMap=new Map(oldBinding.inputs.map(r=>[r.path,r]));assert.deepEqual(binding.inputs.filter(r=>!oldMap.has(r.path)).map(r=>r.path).sort(),added.sort());
assert.deepEqual(binding.inputs.filter(r=>oldMap.has(r.path)&&oldMap.get(r.path).sha256!==r.sha256).map(r=>r.path).sort(),changed.sort());
for(const row of binding.inputs)assert.equal(hash(site+'/'+row.path),row.sha256,row.path);
const pin=json(parent.website+'/tests/fixtures/current-atlas-delivery.json');pin.reviewIntegration=binding.sha256;for(const rel of Object.keys(pin.documents))pin.documents[rel]=hash(site+'/'+rel);
const pinPath=site+'/tests/fixtures/current-atlas-delivery.json';assert.equal(hash(pinPath),hash(parent.website+'/tests/fixtures/current-atlas-delivery.json'));fs.writeFileSync(pinPath,JSON.stringify(pin,null,2)+'\n');
const authored=['components/HeadAtlasViewer.tsx','components/AtlasRegionNavigation.tsx','components/AtlasWorkspaceNavigation.tsx','components/ImagingAtlasShell.tsx','scripts/bind-clinical-review.mjs'];
const rows=[];for(const rel of authored){const row=parent.sourceRows.find(r=>r.path===rel);assert(row);assert.equal(hash(parent.website+'/'+rel),row.sha256);fs.mkdirSync(stage+'/preimages/'+rel.slice(0,rel.lastIndexOf('/')),{recursive:true});fs.copyFileSync(parent.website+'/'+rel,stage+'/preimages/'+rel,fs.constants.COPYFILE_EXCL);rows.push({path:rel,before:row.sha256,after:hash(site+'/'+rel)});}
write(stage+'/PRODUCT_CHANGE.json',{parentReceipt:prep.parentReceipt,parentReceiptSha256:hash(prep.parentReceipt),parentWebsite:parent.website,authored:rows,boundAdded:added,boundChanged:changed,reviewBefore:oldBinding.sha256,reviewAfter:binding.sha256,inputCountBefore:oldBinding.inputs.length,inputCountAfter:binding.inputs.length,clinicalApproval:false,previewChanged:false});
const files=[];function walk(dir,prefix=''){for(const entry of fs.readdirSync(dir,{withFileTypes:true})){assert(!entry.isSymbolicLink());const rel=prefix+entry.name;if(entry.isDirectory())walk(dir+'/'+entry.name,rel+'/');else files.push({path:rel,bytes:fs.statSync(dir+'/'+entry.name).size,sha256:hash(dir+'/'+entry.name)});}}walk(site+'/dist');files.sort((a,b)=>a.path.localeCompare(b.path));assert(files.length>1000);write(stage+'/BUILD_ARTIFACTS.json',{at:new Date().toISOString(),root:site+'/dist',files,actualNewBuild:true,localOnly:true});
console.log(JSON.stringify({review:binding.sha256,boundInputs:binding.inputs.length,authored:rows.length,productionOutputs:files.length}));
